import { createHash } from 'node:crypto';
import type { Boilerplate, ReviewFile, ReviewHunk } from '../../prreview';

/**
 * A whole pull request's unified diff (`git diff` or `gh pr diff`) as files and
 * hunks, each hunk with a stable id and, when it is boilerplate (lockfiles,
 * generated files, snapshots, formatting-only edits, binaries), why.
 */

const LOCKFILES = new Set([
	'package-lock.json',
	'npm-shrinkwrap.json',
	'yarn.lock',
	'pnpm-lock.yaml',
	'bun.lockb',
	'bun.lock',
	'Cargo.lock',
	'go.sum',
	'poetry.lock',
	'uv.lock',
	'Pipfile.lock',
	'Gemfile.lock',
	'composer.lock',
	'flake.lock',
	'mix.lock',
	'pubspec.lock',
	'Podfile.lock',
	'packages.lock.json'
]);

const GENERATED = [
	/(^|\/)(dist|build|out|\.svelte-kit|\.next|node_modules|vendor)\//,
	/(^|\/)(generated|__generated__|gen)\//,
	/\.(generated|gen)\.[a-z0-9]+$/i,
	/\.min\.(js|css)$/i,
	/\.map$/i,
	/\.pb\.go$/,
	/_pb2(_grpc)?\.py$/,
	/\.g\.dart$/
];

const SNAPSHOT = [/(^|\/)__snapshots__\//, /\.snap$/, /\.snapshot$/];

/** Why a whole file is boilerplate, from its path; null when it is not. */
export function fileBoilerplate(file: string): Boilerplate | null {
	const name = file.split('/').pop() ?? file;
	if (LOCKFILES.has(name)) return 'lockfile';
	if (SNAPSHOT.some((r) => r.test(file))) return 'snapshot';
	if (GENERATED.some((r) => r.test(file))) return 'generated';
	return null;
}

const squash = (lines: string[]) => lines.map((l) => l.slice(1).replace(/\s+/g, '')).join('');

/**
 * A hunk that only re-indents, re-wraps or re-spaces: the removed and added
 * lines are the same once whitespace is ignored (and it changes something).
 */
export function formattingOnly(lines: string[]): boolean {
	const removed = lines.filter((l) => l.startsWith('-'));
	const added = lines.filter((l) => l.startsWith('+'));
	if (!removed.length || !added.length) return false;
	return squash(removed) === squash(added);
}

const GENERATED_MARK = /@generated\b|DO NOT EDIT|auto-generated|autogenerated/i;

const HUNK = /^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/;

const unquote = (p: string) => {
	const s = p.trim();
	if (!s.startsWith('"')) return s;
	try {
		return JSON.parse(s) as string;
	} catch {
		return s.slice(1, -1);
	}
};

const stripPrefix = (p: string) => p.replace(/^[ab]\//, '');

/** Parse a whole unified diff into files and hunks. */
export function parsePatch(text: string): ReviewFile[] {
	const files: ReviewFile[] = [];
	const lines = text.replace(/\r\n?/g, '\n').split('\n');
	if (lines.at(-1) === '') lines.pop();
	let file: ReviewFile | null = null;
	let hunk: ReviewHunk | null = null;
	let inHeader = false;

	const closeHunk = () => {
		if (file && hunk) file.hunks.push(hunk);
		hunk = null;
	};
	const closeFile = () => {
		closeHunk();
		if (file) files.push(finish(file));
		file = null;
	};

	for (const line of lines) {
		if (line.startsWith('diff --git ')) {
			closeFile();
			const m = /^diff --git (?:"?a\/)(.+?)"? (?:"?b\/)(.+?)"?$/.exec(line);
			const to = m ? unquote(m[2]) : line.slice(11);
			const from = m ? unquote(m[1]) : to;
			file = {
				path: to,
				oldPath: from !== to ? from : null,
				status: 'M',
				additions: 0,
				deletions: 0,
				boilerplate: null,
				hunks: []
			};
			inHeader = true;
			continue;
		}
		if (!file) continue;
		const f: ReviewFile = file;
		if (inHeader && !line.startsWith('@@')) {
			if (line.startsWith('new file mode')) f.status = 'A';
			else if (line.startsWith('deleted file mode')) f.status = 'D';
			else if (line.startsWith('rename from ')) {
				f.status = 'R';
				f.oldPath = line.slice(12);
			} else if (line.startsWith('rename to ')) f.path = line.slice(10);
			else if (line.startsWith('+++ ') && line !== '+++ /dev/null')
				f.path = stripPrefix(unquote(line.slice(4)));
			else if (/^Binary files .* differ$/.test(line) || line === 'GIT binary patch')
				f.boilerplate = 'binary';
			continue;
		}
		const m = HUNK.exec(line);
		if (m) {
			inHeader = false;
			closeHunk();
			hunk = {
				id: '',
				path: f.path,
				header: line,
				lines: [],
				newStart: Number(m[3]),
				additions: 0,
				deletions: 0,
				boilerplate: null,
				unseen: false
			};
			continue;
		}
		const h = hunk as ReviewHunk | null;
		if (!h) continue;
		if (line.startsWith('+')) {
			h.additions++;
			f.additions++;
		} else if (line.startsWith('-')) {
			h.deletions++;
			f.deletions++;
		} else if (!line.startsWith(' ') && !line.startsWith('\\') && line !== '') continue;
		h.lines.push(line === '' ? ' ' : line);
	}
	closeFile();
	return files;
}

function finish(f: ReviewFile): ReviewFile {
	f.boilerplate ??= fileBoilerplate(f.path);
	if (
		!f.boilerplate &&
		f.hunks.some((h) =>
			h.lines.slice(0, 8).some((l) => l.startsWith('+') && GENERATED_MARK.test(l))
		)
	)
		f.boilerplate = 'generated';
	const seen = new Map<string, number>();
	for (const h of f.hunks) {
		h.path = f.path;
		const id = hunkId(f.path, h);
		const n = (seen.get(id) ?? 0) + 1;
		seen.set(id, n);
		h.id = n > 1 ? `${id}-${n}` : id;
		h.boilerplate = f.boilerplate ?? (formattingOnly(h.lines) ? 'formatting' : null);
	}
	return f;
}

/** A hunk's id: the same file and lines give the same id, whatever else moves. */
export function hunkId(file: string, h: Pick<ReviewHunk, 'header' | 'lines'>): string {
	const hash = createHash('sha1');
	hash.update(file);
	hash.update('\0');
	hash.update(h.header.replace(/^@@[^@]*@@/, ''));
	hash.update('\0');
	hash.update(h.lines.join('\n'));
	return `h${hash.digest('hex').slice(0, 10)}`;
}

/** A hunk as the agent reads it: its file, its header and its lines. */
export const hunkText = (h: ReviewHunk) => [h.header, ...h.lines].join('\n');
